(()=>{const video=document.getElementById('video'),notice=document.getElementById('notice');let handLandmarker,stream,timer,loading=false,generation=0,wasOpenPalm=false;const say=(text,error=false)=>{notice.textContent=text;notice.classList.toggle('error',error)};
function setPalm(value){window.room.palm=value}
function isOpenPalm(points){if(!points||points.length<21)return false;const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),wrist=points[0],mcp=[points[5],points[9],points[13],points[17]],tips=[points[8],points[12],points[16],points[20]],palmWidth=Math.max(dist(points[5],points[17]),.001);let extended=tips.every((tip,i)=>dist(tip,wrist)>dist(mcp[i],wrist)*1.12);let together=tips.slice(0,3).every((tip,i)=>dist(tip,tips[i+1])<palmWidth*.55);let thumbNear=dist(points[4],points[5])<palmWidth*.8;return extended&&together&&thumbNear}
function stopCamera(){generation++;clearInterval(timer);timer=null;stream?.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;setPalm(false);wasOpenPalm=false;loading=false;say('Camera off')}
async function startCamera(){if(loading)return;loading=true;const id=++generation;say('Loading hand tracking');try{const vision=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs');const files=await vision.FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm');if(id!==generation)return;if(!handLandmarker)handLandmarker=await vision.HandLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task'},runningMode:'VIDEO',numHands:1});if(id!==generation)return;stream=await navigator.mediaDevices.getUserMedia({video:{width:320,height:240,facingMode:'user'},audio:false});if(id!==generation){stream.getTracks().forEach(t=>t.stop());stream=null;return}video.srcObject=stream;await video.play();say('Camera on');timer=setInterval(()=>{if(id!==generation||video.readyState<2)return;try{const result=handLandmarker.detectForVideo(video,performance.now());const hand=result.landmarks?.[0];const open=isOpenPalm(hand);setPalm(open);if(open&&!wasOpenPalm)say('Open palm detected');wasOpenPalm=open}catch{say('Hand tracking paused. Press 1 to retry.',true);stopCamera()}},2000)}catch(e){if(id===generation){stopCamera();say(e.name==='NotAllowedError'?'Allow camera access, then press 1 to retry.':'Hand tracking could not start. Check your connection and press 1 to retry.',true)}}finally{if(id===generation)loading=false}}
window.toggleCamera=()=>{if(stream||loading)stopCamera();else startCamera()};window.addEventListener('pagehide',stopCamera)})();
